def daily_temperatures(t: list[int]) -> list[int]:
    res = [0] * len(t)
    st = []  # indices, temperatures strictly decreasing from bottom to top
    for i, x in enumerate(t):
        while st and t[st[-1]] < x:
            j = st.pop()
            res[j] = i - j
        st.append(i)
    return res

